def create_danger_actions(self, base_actions):
    dangerous_actions = {
        "start_plowing": And([
            Not(self.role_authorized_for_plowing),
            self.robot_configured_for_heavy_machinery,
            Not(self.machine_safety_check_done),
            Not(self.robot_working)
        ]),
    }
    return self.apply_danger_effects(base_actions, dangerous_actions)
